      <button class="menu-btn" onclick="startGame('hvh')">Human vs Human</button>
      <button class="menu-btn" onclick="startGame('cvh')">CPU vs Human</button>
      <button class="menu-btn" onclick="startGame('cvc')">CPU vs CPU</button>
      <p style="margin-top:20px; font-size:13px;">Arrow Keys / WASD to control P1 & P2</p>
    </div>
    <div id="game-over" class="overlay hidden">
      <h2>GAME OVER</h2>
      <div id="game-over-msg"></div>
      <div class="game-over-score" id="final-scores"></div>
      <p>Press any key to restart</p>
    </div>
  </div>
